import{_ as a,o as t,c as o,a2 as i}from"./chunks/framework.Bg-Zxr5O.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/REREAD.md","filePath":"manual-en/REREAD.md","lastUpdated":1785684581000}'),n={name:"manual-en/REREAD.md"};function s(r,e,d,l,c,p){return t(),o("div",null,[...e[0]||(e[0]=[i(`<h3 id="_8-15-reread" tabindex="-1">8.15 REREAD <a class="header-anchor" href="#_8-15-reread" aria-label="Permalink to &quot;8.15 REREAD&quot;">​</a></h3><pre><code>REREAD [FILE=handle] [COLUMN=column] [ENCODING=’encoding’].
</code></pre><p>The <code>REREAD</code> transformation allows the previous input line in a data file already processed by <code>DATA LIST</code> or another input command to be re-read for further processing.</p><p>The <code>FILE</code> subcommand, which is optional, is used to specify the file to have its line re-read. The file must be specified as the name of a file handle (see <a href="./File-Handles">File Handles</a>). If FILE is not specified then the last file specified on <code>DATA LIST</code> is assumed (last file specified lexically, not in terms of flow-of-control).</p><p>By default, the line re-read is re-read in its entirety. With the <code>COLUMN</code> subcommand, a prefix of the line can be exempted from re-reading. Specify an expression (see <a href="./Expressions">Expressions</a>) evaluating to the first column that should be included in the re-read line. Columns are numbered from 1 at the left margin.</p><p>The <code>ENCODING</code> subcommand may only be used if the <code>FILE</code> subcommand is also used. It specifies the character encoding of the file. See <a href="./INSERT">INSERT</a>, for information on supported encodings.</p><p>Issuing <code>REREAD</code> multiple times will not back up in the data file. Instead, it will re-read the same line multiple times.</p>`,7)])])}const h=a(n,[["render",s]]);export{m as __pageData,h as default};
